USE studymate;
CREATE TABLE tutor_conversations (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,lesson_id CHAR(36) NOT NULL,title VARCHAR(180) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_tutor_conversation_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_tutor_conversation_lesson FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE,INDEX idx_tutor_conversation_user(user_id,updated_at)) ENGINE=InnoDB;
CREATE TABLE tutor_messages (id CHAR(36) PRIMARY KEY,conversation_id CHAR(36) NOT NULL,role ENUM('user','assistant') NOT NULL,content TEXT NOT NULL,sources_json JSON,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_tutor_message_conversation FOREIGN KEY(conversation_id) REFERENCES tutor_conversations(id) ON DELETE CASCADE,INDEX idx_tutor_message_conversation(conversation_id,created_at)) ENGINE=InnoDB;
CREATE TABLE practice_exams (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,title VARCHAR(200) NOT NULL,question_type ENUM('multiple_choice','true_false','identification','mixed') NOT NULL,difficulty ENUM('easy','medium','hard') NOT NULL,question_count INT UNSIGNED NOT NULL,time_limit_minutes INT UNSIGNED,source_version VARCHAR(64) NOT NULL,generation_key CHAR(64) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_exam_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_exam_user(user_id,updated_at),INDEX idx_exam_cache(generation_key)) ENGINE=InnoDB;
CREATE TABLE practice_exam_lessons (exam_id CHAR(36) NOT NULL,lesson_id CHAR(36) NOT NULL,PRIMARY KEY(exam_id,lesson_id),CONSTRAINT fk_exam_lesson_exam FOREIGN KEY(exam_id) REFERENCES practice_exams(id) ON DELETE CASCADE,CONSTRAINT fk_exam_lesson_lesson FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE practice_exam_questions (id CHAR(36) PRIMARY KEY,exam_id CHAR(36) NOT NULL,lesson_id CHAR(36) NOT NULL,topic_id CHAR(36),position INT UNSIGNED NOT NULL,question_type ENUM('multiple_choice','true_false','identification') NOT NULL,prompt TEXT NOT NULL,choices_json JSON,correct_answer_json JSON NOT NULL,explanation TEXT NOT NULL,CONSTRAINT fk_exam_question_exam FOREIGN KEY(exam_id) REFERENCES practice_exams(id) ON DELETE CASCADE,CONSTRAINT fk_exam_question_lesson FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE,CONSTRAINT fk_exam_question_topic FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE SET NULL,UNIQUE KEY uq_exam_question_position(exam_id,position)) ENGINE=InnoDB;
CREATE TABLE practice_exam_attempts (id CHAR(36) PRIMARY KEY,exam_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,correct_count INT UNSIGNED NOT NULL,total_count INT UNSIGNED NOT NULL,percentage DECIMAL(5,2) NOT NULL,started_at TIMESTAMP NOT NULL,completed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_exam_attempt_exam FOREIGN KEY(exam_id) REFERENCES practice_exams(id) ON DELETE CASCADE,CONSTRAINT fk_exam_attempt_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_exam_attempt_user(user_id,completed_at)) ENGINE=InnoDB;
CREATE TABLE practice_exam_answers (id CHAR(36) PRIMARY KEY,attempt_id CHAR(36) NOT NULL,question_id CHAR(36) NOT NULL,answer_json JSON NOT NULL,is_correct BOOLEAN NOT NULL,CONSTRAINT fk_exam_answer_attempt FOREIGN KEY(attempt_id) REFERENCES practice_exam_attempts(id) ON DELETE CASCADE,CONSTRAINT fk_exam_answer_question FOREIGN KEY(question_id) REFERENCES practice_exam_questions(id) ON DELETE CASCADE,UNIQUE KEY uq_exam_attempt_question(attempt_id,question_id)) ENGINE=InnoDB;
